import { useState } from "react";
import API from "../services/api";

function JobForm() {

    const [job, setJob] = useState({
        name: "",
        command: "",
        scheduledTime: "",
        cronExpression: ""
    });

    const handleChange = (e) => {

        setJob({
            ...job,
            [e.target.name]: e.target.value
        });
    };

    const handleSubmit = async (e) => {

        e.preventDefault();

        try {

            await API.post("", job);

            alert("Job Created!");

            setJob({
                name: "",
                command: "",
                scheduledTime: "",
                cronExpression: ""
            });

        } catch (error) {

            console.error(error);

            alert("Failed to create job");
        }
    };

    return (

        <div>

            <h2>Create Job</h2>

            <form onSubmit={handleSubmit}>

                <input
                    type="text"
                    name="name"
                    placeholder="Job Name"
                    value={job.name}
                    onChange={handleChange}
                />

                <br /><br />

                <input
                    type="text"
                    name="command"
                    placeholder="Command"
                    value={job.command}
                    onChange={handleChange}
                />

                <br /><br />

                <input
                    type="datetime-local"
                    name="scheduledTime"
                    value={job.scheduledTime}
                    onChange={handleChange}
                />

                <br /><br />

                <input
                    type="text"
                    name="cronExpression"
                    placeholder="Cron Expression"
                    value={job.cronExpression}
                    onChange={handleChange}
                />

                <br /><br />

                <button type="submit">
                    Create Job
                </button>

            </form>

        </div>
    );
}

export default JobForm;
